"""Offline boundary checks; generated bytes only, never real firmware."""
import gzip
import hashlib
import io
import zipfile

import httpx
import pytest

from fmr_extractor.range_extractor import RemoteZip, RangeNotSupportedError
from fmr_extractor import extract_partitions_via_range
from verify_phase1_live import MeteredClient, read_metadata, select_seed, verify_download


def sample():
    config = {'codename': 'sample', 'source_codename': 'sample_global',
              'version': 'V1.0.TEST', 'expected_md5': 'a' * 32, 'filename': 'sample.zip'}
    row = {'codename': 'sample_global', 'version': 'V1.0.TEST', 'method': 'Recovery',
           'branch': 'Stable', 'md5': 'a' * 32, 'link': 'https://bigota.d.miui.com/V1.0.TEST/sample.zip',
           'android': '11.0', 'date': '2022-01-01'}
    return {'sample_global': ['Sample Global', 'Sample']}, [row], config


def test_seed_selects_one_exact_stable_build_and_rejects_conflicts():
    devices, rows, config = sample()
    device, firmware = select_seed(devices, rows + [{**rows[0], 'branch': 'Stable Beta'}], config)
    assert device['codename'] == 'sample' and firmware['md5'] == 'a' * 32
    with pytest.raises(ValueError):
        select_seed(devices, rows + rows, config)
    for change in [{'link': 'https://attacker.example/sample.zip'}, {'md5': 'b' * 32}, {'link': 'https://bigota.d.miui.com/different.zip'}]:
        with pytest.raises(ValueError):
            select_seed(devices, [{**rows[0], **change}], config)


def test_metadata_requires_a_pinned_recognized_source_before_fetch():
    def forbidden(request):
        raise AssertionError('Untrusted metadata must not be fetched')
    with httpx.Client(transport=httpx.MockTransport(forbidden)) as client:
        for url in ['http://raw.githubusercontent.com/a', 'https://127.0.0.1/data/latest.yml',
                    'https://raw.githubusercontent.com/XiaomiFirmwareUpdater/miui-updates-tracker/master/data/latest.yml']:
            with pytest.raises(ValueError):
                read_metadata(client, url)


def test_ignored_range_is_closed_without_consuming_a_body():
    class ForbiddenBody(httpx.SyncByteStream):
        def __iter__(self):
            raise AssertionError('Ignored Range body consumed')
            yield b''
    metrics = {'range_bytes': 0, 'range_requests': 0}
    with MeteredClient(metrics, transport=httpx.MockTransport(lambda req: httpx.Response(200, stream=ForbiddenBody()))) as client:
        with pytest.raises(RangeNotSupportedError):
            RemoteZip('https://bigota.d.miui.com/sample.zip', client, 262144000)
    assert metrics == {'range_bytes': 0, 'range_requests': 1}


def test_real_range_reader_is_metered_and_never_fetches_unrelated_entries(tmp_path):
    buffer = io.BytesIO()
    boot = b'ANDROID!' + b'\0' * (65536 - 8)
    with zipfile.ZipFile(buffer, 'w', compression=zipfile.ZIP_STORED) as archive:
        archive.writestr('boot.img', boot)
        archive.writestr('unrelated.bin', b'x' * 1048576)
    blob = buffer.getvalue()
    def handler(request):
        start, end = map(int, request.headers['Range'].removeprefix('bytes=').split('-'))
        return httpx.Response(206, headers={'Content-Range': f'bytes {start}-{end}/{len(blob)}'}, stream=httpx.ByteStream(blob[start:end+1]))
    metrics = {'range_bytes': 0, 'range_requests': 0}
    with MeteredClient(metrics, transport=httpx.MockTransport(handler)) as client:
        images = extract_partitions_via_range('https://bigota.d.miui.com/sample.zip', tmp_path, http_client=client)
    assert images['boot'].read_bytes() == boot
    assert 65536 <= metrics['range_bytes'] < len(blob) / 4


def test_download_checks_complete_bytes_not_just_the_hash_header():
    payload = gzip.compress(b'Synthetic diagnostic only', mtime=0)
    digest = hashlib.sha256(payload).hexdigest()
    image = {'file_size_bytes': len(payload), 'sha256_hash': digest}
    def client_for(data):
        return httpx.Client(transport=httpx.MockTransport(lambda req: httpx.Response(200,
            headers={'Content-Type': 'application/gzip', 'X-FindMyROM-SHA256': digest, 'X-FindMyROM-Cache': 'HIT'}, content=data)))
    with client_for(payload) as client:
        assert verify_download(client, '/api/dl?test=1', image)
    with client_for(payload[:-1] + bytes([payload[-1] ^ 1])) as client:
        with pytest.raises(ValueError):
            verify_download(client, '/api/dl?test=1', image)
